package gitproto

import (
	"bytes"
	"context"
	"errors"
	"io"
	"maps"
	"strings"
	"testing"

	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/format/pktline"
)

var (
	maxA = plumbing.NewHash(strings.Repeat("a", 40))
	maxB = plumbing.NewHash(strings.Repeat("b", 40))
	maxC = plumbing.NewHash(strings.Repeat("c", 40))
	maxD = plumbing.NewHash(strings.Repeat("d", 40))
)

func pktBody(t *testing.T, lines ...string) []byte {
	t.Helper()
	var buf bytes.Buffer
	for _, l := range lines {
		if _, err := pktline.WriteString(&buf, l+"\n"); err != nil {
			t.Fatal(err)
		}
	}
	if err := pktline.WriteFlush(&buf); err != nil {
		t.Fatal(err)
	}
	return buf.Bytes()
}

// maximalConn serves a v2 advertisement and one ls-refs response, and records
// the ls-refs request.
type maximalConn struct {
	stubConn

	adv     []byte
	lsRefs  []byte
	request []byte
}

func (c *maximalConn) RequestInfoRefs(context.Context, string, string) ([]byte, error) {
	return c.adv, nil
}

func (c *maximalConn) PostRPCStreamBody(_ context.Context, _ string, body io.Reader, _ bool, _ string) (io.ReadCloser, error) {
	var err error
	if c.request, err = io.ReadAll(body); err != nil {
		return nil, err
	}
	return io.NopCloser(bytes.NewReader(c.lsRefs)), nil
}

func TestListMaximalTips(t *testing.T) {
	conn := &maximalConn{
		adv: pktBody(t, "version 2", "ls-refs=unborn "+MaximalFeature, "fetch"),
		lsRefs: pktBody(t,
			maxA.String()+" HEAD symref-target:refs/heads/main "+MaximalFeature,
			maxA.String()+" refs/heads/main "+MaximalFeature,
			maxB.String()+" refs/heads/old",
			maxC.String()+" refs/tags/v1 peeled:"+maxB.String(),
		),
	}
	tips, err := ListMaximalTips(t.Context(), conn, []string{"refs/heads/", "refs/tags/"}, false)
	if err != nil {
		t.Fatal(err)
	}
	if tips == nil {
		t.Fatal("tips = nil for a server advertising the feature")
	}
	req := string(conn.request)
	for _, want := range []string{"command=ls-refs", MaximalFeature, "ref-prefix refs/heads/", "ref-prefix refs/tags/"} {
		if !strings.Contains(req, want) {
			t.Errorf("request %q lacks %q", req, want)
		}
	}
	if tips.Marked() != 1 || tips.Unmarked() != 2 {
		t.Fatalf("marked=%d unmarked=%d, want 1 and 2 (HEAD skipped)", tips.Marked(), tips.Unmarked())
	}
}

func TestListMaximalTipsUnadvertised(t *testing.T) {
	for name, adv := range map[string][]string{
		"no feature":  {"version 2", "ls-refs=unborn", "fetch"},
		"no ls-refs":  {"version 2", "fetch"},
		"v1 response": {maxA.String() + " refs/heads/main\x00report-status"},
	} {
		t.Run(name, func(t *testing.T) {
			conn := &maximalConn{adv: pktBody(t, adv...)}
			tips, err := ListMaximalTips(t.Context(), conn, nil, false)
			if !errors.Is(err, ErrMaximalUnsupported) {
				t.Fatalf("err = %v, want ErrMaximalUnsupported", err)
			}
			if tips != nil {
				t.Fatal("tips != nil without the advertisement")
			}
			if conn.request != nil {
				t.Fatalf("sent ls-refs %q to a server that did not advertise %s", conn.request, MaximalFeature)
			}
		})
	}
}

// AssumeTargetMaximal's path: the argument goes to a v2 server that does not
// advertise it, but never to one without v2 ls-refs.
func TestListMaximalTipsAssumed(t *testing.T) {
	conn := &maximalConn{
		adv:    pktBody(t, "version 2", "ls-refs=unborn", "fetch"),
		lsRefs: pktBody(t, maxA.String()+" refs/heads/main "+MaximalFeature),
	}
	tips, err := ListMaximalTips(t.Context(), conn, nil, true)
	if err != nil {
		t.Fatal(err)
	}
	if tips == nil || tips.Marked() != 1 {
		t.Fatalf("tips = %+v, want one marked ref", tips)
	}
	if !strings.Contains(string(conn.request), MaximalFeature) {
		t.Fatalf("request %q lacks %s", conn.request, MaximalFeature)
	}

	v1 := &maximalConn{adv: pktBody(t, maxA.String()+" refs/heads/main\x00report-status")}
	if _, err := ListMaximalTips(t.Context(), v1, nil, true); !errors.Is(err, ErrMaximalUnsupported) {
		t.Fatalf("err = %v, want ErrMaximalUnsupported for a v1 server", err)
	}
	if v1.request != nil {
		t.Fatalf("sent ls-refs %q to a v1 server", v1.request)
	}
}

func TestMaximalTipsReduce(t *testing.T) {
	tips := &MaximalTips{
		marked:   map[plumbing.ReferenceName]plumbing.Hash{"refs/heads/main": maxA},
		unmarked: map[plumbing.ReferenceName]plumbing.Hash{"refs/heads/old": maxB, "refs/tags/v1": maxC},
	}
	full := map[plumbing.ReferenceName]plumbing.Hash{
		"refs/heads/main":  maxA,
		"refs/heads/old":   maxB,
		"refs/tags/v1":     maxC,
		"refs/pull/1/head": maxD, // unlisted: kept
	}
	cases := map[string]struct {
		tips  *MaximalTips
		haves map[plumbing.ReferenceName]plumbing.Hash
		want  map[plumbing.ReferenceName]plumbing.Hash
	}{
		"drops unmarked": {
			tips: tips, haves: full,
			want: map[plumbing.ReferenceName]plumbing.Hash{"refs/heads/main": maxA, "refs/pull/1/head": maxD},
		},
		"nil keeps all": {tips: nil, haves: full, want: full},
		"marked ref moved keeps all": {
			tips: tips,
			haves: map[plumbing.ReferenceName]plumbing.Hash{
				"refs/heads/main": maxD, "refs/heads/old": maxB, "refs/tags/v1": maxC,
			},
			want: map[plumbing.ReferenceName]plumbing.Hash{
				"refs/heads/main": maxD, "refs/heads/old": maxB, "refs/tags/v1": maxC,
			},
		},
		"marked ref missing keeps all": {
			tips:  tips,
			haves: map[plumbing.ReferenceName]plumbing.Hash{"refs/heads/old": maxB},
			want:  map[plumbing.ReferenceName]plumbing.Hash{"refs/heads/old": maxB},
		},
		"unmarked ref moved stays": {
			tips: tips,
			haves: map[plumbing.ReferenceName]plumbing.Hash{
				"refs/heads/main": maxA, "refs/heads/old": maxD, "refs/tags/v1": maxC,
			},
			want: map[plumbing.ReferenceName]plumbing.Hash{"refs/heads/main": maxA, "refs/heads/old": maxD},
		},
	}
	for name, tc := range cases {
		t.Run(name, func(t *testing.T) {
			if got := tc.tips.Reduce(tc.haves); !maps.Equal(got, tc.want) {
				t.Fatalf("Reduce = %v, want %v", got, tc.want)
			}
		})
	}
}

package gitproto

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"strings"

	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/transport"
)

// MaximalFeature is entiredb's ls-refs extension. It is the capability
// feature, the request argument, and the ref attribute. A server that
// receives it marks each listed ref whose commit no other listed ref reaches.
// It leaves a ref unmarked only when it has proved that another listed ref's
// commit reaches it, so the marked refs imply the history of every listed ref.
const MaximalFeature = "entire-maximal"

// ErrMaximalUnsupported reports that a server does not advertise
// MaximalFeature over protocol v2.
var ErrMaximalUnsupported = errors.New("server does not advertise " + MaximalFeature)

// MaximalTips is a target's ls-refs listing with the MaximalFeature marks.
// Reduce uses it to drop redundant haves.
type MaximalTips struct {
	marked   map[plumbing.ReferenceName]plumbing.Hash
	unmarked map[plumbing.ReferenceName]plumbing.Hash
}

// Marked and Unmarked report the listing's size, for logs and tests.
func (m *MaximalTips) Marked() int   { return len(m.marked) }
func (m *MaximalTips) Unmarked() int { return len(m.unmarked) }

// ListMaximalTips lists conn's upload-pack refs under prefixes with the
// MaximalFeature marks. It returns ErrMaximalUnsupported, before sending
// ls-refs, when the server does not speak protocol v2 or, unless
// assumeSupported is set, does not advertise the feature. Protocol v2 forbids
// an argument the server did not advertise, so set assumeSupported only for a
// server known to accept it; one that does not fails the ls-refs request.
//
// List only refs the source also holds. The source ignores a have it lacks,
// and a marked tip it lacks hides the unmarked refs behind it, so the fetch
// carries history the target already has. That costs bytes, never
// correctness.
func ListMaximalTips(ctx context.Context, conn Conn, prefixes []string, assumeSupported bool) (*MaximalTips, error) {
	data, err := RequestInfoRefs(ctx, conn, transport.UploadPackService, GitProtocolV2)
	if err != nil {
		return nil, err
	}
	caps, err := DecodeV2Capabilities(bytes.NewReader(data))
	if err != nil {
		// A v1 advertisement: the server did not negotiate v2.
		return nil, ErrMaximalUnsupported
	}
	if !caps.Supports("ls-refs") || (!assumeSupported && !caps.LSRefsSupports(MaximalFeature)) {
		return nil, ErrMaximalUnsupported
	}
	args := []string{MaximalFeature}
	for _, prefix := range prefixes {
		args = append(args, "ref-prefix "+prefix)
	}
	body, err := EncodeCommand("ls-refs", caps.RequestCapabilities(), args)
	if err != nil {
		return nil, err
	}
	resp, err := PostRPC(ctx, conn, transport.UploadPackService, body, true, "upload-pack ls-refs "+MaximalFeature)
	if err != nil {
		return nil, err
	}
	return decodeMaximalLSRefs(bytes.NewReader(resp))
}

func decodeMaximalLSRefs(r *bytes.Reader) (*MaximalTips, error) {
	m := &MaximalTips{
		marked:   map[plumbing.ReferenceName]plumbing.Hash{},
		unmarked: map[plumbing.ReferenceName]plumbing.Hash{},
	}
	reader := NewPacketReader(r)
	for {
		kind, payload, err := reader.ReadPacket()
		if err != nil {
			return nil, err
		}
		if kind == PacketFlush {
			return m, nil
		}
		if kind != PacketData {
			return nil, fmt.Errorf("unexpected packet type %v in ls-refs response", kind)
		}
		fields := strings.Fields(strings.TrimSpace(string(payload)))
		if len(fields) < 2 {
			return nil, fmt.Errorf("malformed ls-refs response line %q", payload)
		}
		name := plumbing.ReferenceName(fields[1])
		// HEAD is not a have: the branch it names carries the same mark.
		if fields[0] == "unborn" || name == plumbing.HEAD {
			continue
		}
		if !plumbing.IsHash(fields[0]) {
			return nil, fmt.Errorf("malformed ls-refs object id %q", fields[0])
		}
		hash := plumbing.NewHash(fields[0])
		marked := false
		for _, attr := range fields[2:] {
			if attr == MaximalFeature {
				marked = true
				break
			}
		}
		if marked {
			m.marked[name] = hash
		} else {
			m.unmarked[name] = hash
		}
	}
}

// Reduce returns haves without the refs the listing proved redundant. A nil
// receiver returns haves unchanged.
//
// An unmarked ref is implied only through a marked ref that reaches it, and
// the listing does not say which one. So Reduce drops anything only when every
// marked ref is in haves at its listed hash. A ref that moved since the
// listing, such as one this run pushed, keeps the whole map unreduced. An
// unmarked ref is dropped only at its listed hash. Refs the listing did not
// cover stay.
func (m *MaximalTips) Reduce(haves map[plumbing.ReferenceName]plumbing.Hash) map[plumbing.ReferenceName]plumbing.Hash {
	if m == nil || len(m.unmarked) == 0 {
		return haves
	}
	for name, hash := range m.marked {
		if got, ok := haves[name]; !ok || got != hash {
			return haves
		}
	}
	out := make(map[plumbing.ReferenceName]plumbing.Hash, len(haves))
	for name, hash := range haves {
		if listed, ok := m.unmarked[name]; ok && listed == hash {
			continue
		}
		out[name] = hash
	}
	return out
}
package syncer

import (
	"context"
	"errors"
	"log/slog"
	"strings"

	"entire.io/entire/git-sync/internal/gitproto"
	"entire.io/entire/git-sync/internal/planner"
	"github.com/go-git/go-git/v6/plumbing"
)

// fetchHaves returns the target refs a source fetch offers as haves:
// targetRefs without the refs the target proved redundant (see
// maximalTips), then narrowed by planner.FetchHaves.
//
// The reduction comes first because it needs every marked ref in the map.
// FetchHaves then drops independent-history refs, and a marked one of those
// implies only its own history, which FetchHaves already gives up.
func (s *syncSession) fetchHaves(
	ctx context.Context,
	targetRefs map[plumbing.ReferenceName]plumbing.Hash,
	plans []planner.BranchPlan,
) map[plumbing.ReferenceName]plumbing.Hash {
	reduced := s.maximalTips(ctx).Reduce(targetRefs)
	return planner.FetchHaves(reduced, plans, s.cfg.IndependentHistoryRefPrefixes)
}

// maximalTips asks the target, once per run, which of its refs no other ref
// reaches (gitproto.MaximalFeature). Every target tip is a have by default,
// and most tips are ancestors of others, so a large target sends far more
// have lines than the fetch needs.
//
// It returns nil, and the caller keeps every tip, when the target does not
// advertise the feature (unless Config.AssumeTargetMaximal is set), when protocol v1 is pinned, when the target has too
// few refs to gain anything, when the target is reached over SSH, or when the
// listing fails. An SSH server whose sshd does not accept GIT_PROTOCOL answers
// the v2 probe with its full v0 ref advertisement, which can be megabytes for
// a ref list this run already holds. HTTP and remote helpers answer v2 with a
// short capability list. The listing is an
// optimization, so a failure is logged and not returned.
//
// The listing covers only the namespaces this run mirrors. A marked target ref
// the source lacks would hide the refs behind it from the fetch. Mirrored refs
// came from the source, while a target-only namespace may not have.
func (s *syncSession) maximalTips(ctx context.Context) *gitproto.MaximalTips {
	t := s.target
	if t == nil || t.conn == nil {
		return nil
	}
	if t.maximalListed {
		return t.maximal
	}
	t.maximalListed = true
	if s.cfg.ProtocolMode == protocolModeV1 || len(t.refMap) < 2 || isSSHEndpoint(t.conn) {
		return nil
	}
	tips, err := gitproto.ListMaximalTips(ctx, t.conn, maximalRefPrefixes(planConfig(s.cfg)), s.cfg.AssumeTargetMaximal)
	if err != nil {
		if s.logger != nil && !errors.Is(err, gitproto.ErrMaximalUnsupported) {
			s.logger.Debug("target maximal tips unavailable; offering every target tip as a have", slog.Any("error", err))
		}
		return nil
	}
	if s.logger != nil {
		s.logger.Debug("target maximal tips", slog.Int("marked", tips.Marked()), slog.Int("unmarked", tips.Unmarked()))
	}
	t.maximal = tips
	return tips
}

// maximalRefPrefixes is the target-side scope of the maximal listing: the
// include prefixes when set, otherwise the namespaces the source listing uses.
// A mapping keeps its kind (branch or tag), so the same prefixes cover its
// target name. A ref outside the scope is unlisted, and Reduce keeps it.
func maximalRefPrefixes(cfg planner.PlanConfig) []string {
	var include []string
	for _, p := range cfg.IncludeRefPrefixes {
		if p = strings.TrimSpace(p); p != "" {
			include = append(include, p)
		}
	}
	if len(include) > 0 {
		return include
	}
	return planner.RefPrefixes(cfg)
}

func isSSHEndpoint(conn gitproto.Conn) bool {
	ep := conn.Endpoint()
	return ep != nil && (ep.Scheme == "ssh" || ep.Scheme == "git+ssh")
}

package syncer

import (
	"context"
	"slices"
	"testing"

	"entire.io/entire/git-sync/internal/gitproto"
	"github.com/go-git/go-billy/v6"
	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
)

// maximalFixture is a source whose branch master has two older branches
// behind it, already mirrored to a target. Every target tip but master's is
// an ancestor of master's.
type maximalFixture struct {
	source       *git.Repository
	sourceFS     billy.Filesystem
	target       *git.Repository
	targetServer *smartHTTPRepoServer
	sourceURL    string
	haves        *haveRecorder
	older        []plumbing.ReferenceName
	assume       bool
}

func newMaximalFixture(t *testing.T, advertise bool) *maximalFixture {
	t.Helper()
	sourceRepo, sourceFS := newSourceRepo(t)
	targetRepo, _ := newSourceRepo(t)
	makeCommits(t, sourceRepo, sourceFS, 3)
	f := &maximalFixture{source: sourceRepo, sourceFS: sourceFS, target: targetRepo, haves: &haveRecorder{}}

	commit, err := sourceRepo.CommitObject(f.tip(t, plumbing.NewBranchReferenceName(testBranch)))
	if err != nil {
		t.Fatalf("read master: %v", err)
	}
	for _, name := range []string{"older-a", "older-b"} {
		if commit, err = commit.Parent(0); err != nil {
			t.Fatalf("walk master: %v", err)
		}
		ref := plumbing.NewBranchReferenceName(name)
		if err := sourceRepo.Storer.SetReference(plumbing.NewHashReference(ref, commit.Hash)); err != nil {
			t.Fatalf("set %s: %v", ref, err)
		}
		f.older = append(f.older, ref)
	}

	sourceServer := newSmartHTTPRepoServerV2(t, sourceRepo)
	f.targetServer = newSmartHTTPRepoServerV2(t, targetRepo)
	f.targetServer.receivePackThinCap = true
	f.targetServer.lsRefsMaximal = advertise
	t.Cleanup(sourceServer.Close)
	t.Cleanup(f.targetServer.Close)
	f.haves.attach(sourceServer)
	f.sourceURL = sourceServer.RepoURL()

	if _, err := f.run(t, modeReplicate, ""); err != nil {
		t.Fatalf("seed replicate: %v", err)
	}
	assertSameRefs(t, sourceRepo, targetRepo)
	f.haves.take()
	return f
}

func (f *maximalFixture) run(t *testing.T, mode, protocol string) (Result, error) {
	t.Helper()
	return Run(context.Background(), Config{
		Source:       Endpoint{URL: f.sourceURL},
		Target:       Endpoint{URL: f.targetServer.RepoURL()},
		Mode:         mode,
		ProtocolMode: protocol,
		Branches:     []string{testBranch, "older-a", "older-b"},

		AssumeTargetMaximal: f.assume,
	})
}

func (f *maximalFixture) tip(t *testing.T, ref plumbing.ReferenceName) plumbing.Hash {
	t.Helper()
	r, err := f.source.Reference(ref, true)
	if err != nil {
		t.Fatalf("read %s: %v", ref, err)
	}
	return r.Hash()
}

// advance moves master on the source and returns its old tip.
func (f *maximalFixture) advance(t *testing.T) plumbing.Hash {
	t.Helper()
	before := f.tip(t, plumbing.NewBranchReferenceName(testBranch))
	makeCommits(t, f.source, f.sourceFS, 1)
	return before
}

func (f *maximalFixture) olderTips(t *testing.T) []plumbing.Hash {
	t.Helper()
	out := make([]plumbing.Hash, 0, len(f.older))
	for _, ref := range f.older {
		out = append(out, f.tip(t, ref))
	}
	return out
}

func assertEveryFetchHaves(t *testing.T, fetches [][]plumbing.Hash, want ...plumbing.Hash) {
	t.Helper()
	if len(fetches) == 0 {
		t.Fatal("no fetch reached the source")
	}
	for _, got := range fetches {
		assertFetchHaves(t, got, want...)
	}
}

// The case the feature exists for: the target marks only master, so the fetch
// offers master's old tip alone. The older branches are its ancestors.
func TestRun_IntegrationMaximalTipsShrinkHaves(t *testing.T) {
	for _, mode := range []string{modeSync, modeReplicate} {
		t.Run(mode, func(t *testing.T) {
			f := newMaximalFixture(t, true)
			before := f.advance(t)
			if _, err := f.run(t, mode, ""); err != nil {
				t.Fatalf("%s: %v", mode, err)
			}
			assertEveryFetchHaves(t, f.haves.take(), before)
			assertSameRefs(t, f.source, f.target)
			if args := f.targetServer.LastLSRefsArgs(); !slices.Contains(args, gitproto.MaximalFeature) {
				t.Errorf("target ls-refs args = %v, want %s", args, gitproto.MaximalFeature)
			}
		})
	}
}

// A target that does not advertise the feature never sees the argument, and
// every target tip stays a have.
func TestRun_IntegrationMaximalTipsUnadvertisedKeepsEveryTip(t *testing.T) {
	f := newMaximalFixture(t, false)
	before := f.advance(t)
	if _, err := f.run(t, modeReplicate, ""); err != nil {
		t.Fatalf("replicate: %v", err)
	}
	assertEveryFetchHaves(t, f.haves.take(), append(f.olderTips(t), before)...)
	assertSameRefs(t, f.source, f.target)
	if args := f.targetServer.LastLSRefsArgs(); slices.Contains(args, gitproto.MaximalFeature) {
		t.Errorf("target ls-refs args = %v; sent an argument the target did not advertise", args)
	}
}

// Pinning protocol v1 keeps the target listing off v2 entirely.
func TestRun_IntegrationMaximalTipsSkippedUnderV1(t *testing.T) {
	f := newMaximalFixture(t, true)
	f.targetServer.mu.Lock()
	f.targetServer.lsRefsArgs = nil
	f.targetServer.mu.Unlock()
	f.advance(t)
	if _, err := f.run(t, modeReplicate, protocolModeV1); err != nil {
		t.Fatalf("replicate: %v", err)
	}
	assertSameRefs(t, f.source, f.target)
	if args := f.targetServer.LastLSRefsArgs(); args != nil {
		t.Errorf("target ls-refs args = %v, want no ls-refs under protocol v1", args)
	}
}

// mirror-pipeline's case: entiredb accepts the argument before it advertises
// it, so the caller opts in and the haves shrink anyway.
func TestRun_IntegrationMaximalTipsAssumedWithoutAdvertisement(t *testing.T) {
	f := newMaximalFixture(t, false)
	f.assume = true
	before := f.advance(t)
	if _, err := f.run(t, modeReplicate, ""); err != nil {
		t.Fatalf("replicate: %v", err)
	}
	assertEveryFetchHaves(t, f.haves.take(), before)
	assertSameRefs(t, f.source, f.target)
	if args := f.targetServer.LastLSRefsArgs(); !slices.Contains(args, gitproto.MaximalFeature) {
		t.Errorf("target ls-refs args = %v, want %s", args, gitproto.MaximalFeature)
	}
}

// A target that rejects the assumed argument fails only the listing: the run
// offers every tip and completes.
func TestRun_IntegrationMaximalTipsAssumedButRejected(t *testing.T) {
	f := newMaximalFixture(t, false)
	f.assume = true
	f.targetServer.lsRefsRejectMaximal = true
	before := f.advance(t)
	if _, err := f.run(t, modeReplicate, ""); err != nil {
		t.Fatalf("replicate: %v", err)
	}
	assertEveryFetchHaves(t, f.haves.take(), append(f.olderTips(t), before)...)
	assertSameRefs(t, f.source, f.target)
}
