// GitProtocolV2 is the value passed via the Git-Protocol header / GIT_PROTOCOL
// env var to negotiate protocol v2 with the remote.
const GitProtocolV2 = "version=2"

// RefService encapsulates the result of source ref discovery and the negotiated
// protocol, providing methods for subsequent fetch and pack operations.
type RefService struct {
	Protocol string // "v1" or "v2"
	V1Adv    *packp.AdvRefs
	V2Caps   *V2Capabilities
	// HeadTarget is the branch that HEAD points to on the source, when
	// advertised as a symref. Empty for detached HEAD or when the source
	// does not advertise symref information.
	HeadTarget plumbing.ReferenceName
	// Verbose, when true, streams source-side sideband progress ("Counting
	// objects", "Compressing objects", ...) to stderr and asks the source
	// upload-pack to emit progress by not sending the no-progress option.
	Verbose bool
	// HeadUnborn is true when the source reported HEAD as unborn — its
	// symref target does not exist. That is ALL it means. It is emphatically
	// NOT a statement that the repository is empty: git emits the unborn line
	// for any dangling HEAD, so a repository holding refs/heads/other while
	// HEAD points at a never-created refs/heads/main reports unborn too, and
	// hiding (uploadpack.hideRefs) can reduce that repository's whole
	// advertisement to the unborn line alone. Verified against git 2.53.
	//
	// It is therefore a NECESSARY condition for emptiness and never a
	// sufficient one: a truly empty repository always reports unborn, so its
	// absence is a reliable disqualifier, but its presence proves nothing
	// about refs the reader cannot see. A caller that needs to act on
	// emptiness must obtain that from the server's own repository state; use
	// this only to cross-check such an assertion.
	//
	// False means "not reported", NOT "the source has commits": a v1 source,
	// or a v2 source that does not advertise ls-refs=unborn, leaves it false
	// however empty it is.
	HeadUnborn bool

	// SkippedRefCount is how many advertised ref names were dropped as invalid
	// (see PartitionRefNames). Surfaced because a non-zero count is
	// load-bearing for any caller reasoning about an empty ref set: names
	// dropped here leave refs empty while the repository plainly has some,
	// which is indistinguishable from emptiness by ref count alone.
	//
	// A count, not the names: every consumer asks only whether any were
	// dropped, and the names are already reported to the operator by
	// WarnSkippedRefNames at the decode boundary. Retaining the slice pinned
	// it to this struct — which outlives the pack fetch and push — for the
	// whole run, megabytes of it on a source advertising many invalid names,
	// purely to answer a boolean.
	//
	// Set on every construction path, v1 and v2 alike. It was populated at
	// only one of four before, leaving the corroboration silently vacuous on
	// v1; newV1RefService exists so a new path cannot forget.
	SkippedRefCount int
}

// newV1RefService builds the v1 RefService. All three v1 construction sites go
// through it: hand-built literals are how SkippedRefCount came to be set on one
// path and silently left zero on the others, which reads to a caller as
// "nothing was dropped".
func newV1RefService(adv *packp.AdvRefs, skippedRefCount int) *RefService {
	return &RefService{
		Protocol:        "v1",
		V1Adv:           adv,
		HeadTarget:      headTargetFromAdv(adv),
		SkippedRefCount: skippedRefCount,
	}
}

// ListSourceRefs discovers refs from the source using the configured protocol mode.
// Returns the list of refs and a RefService for subsequent operations.
func ListSourceRefs(ctx context.Context, conn Conn, protocolMode string, refPrefixes []string) ([]*plumbing.Reference, *RefService, error) {
	switch protocolMode {
	case "v1":
		adv, refs, skippedCount, err := listSourceRefsV1(ctx, conn)
		if err != nil {
			return nil, nil, err
		}
		return refs, newV1RefService(adv, skippedCount), nil

	case "auto", "v2":
		data, err := RequestInfoRefs(ctx, conn, transport.UploadPackService, GitProtocolV2)
		if err != nil {
			if protocolMode == "auto" && isSSHScheme(conn) {
				refs, svc, v1Err := listSourceRefsAutoV1(ctx, conn)
				if v1Err != nil {
					return nil, nil, errors.Join(err, v1Err)
				}
				return refs, svc, nil
			}
			return nil, nil, err
		}
		if caps, err := DecodeV2Capabilities(bytes.NewReader(data)); err == nil {
			if !caps.Supports("ls-refs") || !caps.Supports("fetch") {
				return nil, nil, errors.New("source does not advertise required protocol v2 commands")
			}
			refs, headTarget, unborn, skippedCount, err := listSourceRefsV2(ctx, conn, caps, refPrefixes)
			if err != nil {
				return nil, nil, err
			}
			return refs, &RefService{Protocol: "v2", V2Caps: caps, HeadTarget: headTarget, HeadUnborn: unborn, SkippedRefCount: skippedCount}, nil
		}
		if protocolMode == "v2" {
			return nil, nil, errors.New("source did not negotiate protocol v2")
		}
		// Fall back to v1
		adv, err := decodeV1AdvRefs(data)
		if err != nil {
			return nil, nil, err
		}
		refs, skipped, err := AdvRefsToSlice(adv)
		if err != nil {
			return nil, nil, err
		}
		WarnSkippedRefNames(conn.ProgressWriter(), "source", skipped)
		return refs, newV1RefService(adv, len(skipped)), nil

	default:
		return nil, nil, fmt.Errorf("unsupported protocol mode %q", protocolMode)
	}
}

func listSourceRefsAutoV1(ctx context.Context, conn Conn) ([]*plumbing.Reference, *RefService, error) {
	adv, refs, skippedCount, err := listSourceRefsV1(ctx, conn)
	if err != nil {
		return nil, nil, err
	}
	return refs, newV1RefService(adv, skippedCount), nil
}

func isSSHScheme(conn Conn) bool {
	if conn == nil || conn.Endpoint() == nil {
		return false
	}
	switch conn.Endpoint().Scheme {
	case "ssh", "git+ssh":
		return true
	}
	return false
}

// AdvertisedRefsV1 fetches and decodes v1 advertised refs for the given service.
func AdvertisedRefsV1(ctx context.Context, conn Conn, service string) (*packp.AdvRefs, error) {
	data, err := RequestInfoRefs(ctx, conn, service, "")
	if err != nil {
		return nil, err
	}
	return decodeV1AdvRefs(data)
}

// AdvRefsToSlice converts an AdvRefs to a slice of references.
//
// Peeled tag entries (names ending in "^{}") are dropped: they are
// wire-protocol metadata exposing the commit a tag points to, not real refs.
// Including them in target ref maps causes the planner to schedule a delete
// for a non-existent ref, which receive-pack rejects with HTTP 400
// "invalid reference name".
// Names a remote advertises are untrusted, so anything git would reject is
// dropped here and returned as skipped for the caller to report. Filtering at
// the decode boundary means every path that reads an advertisement is covered
// without each one remembering to ask.
func AdvRefsToSlice(ar *packp.AdvRefs) (refs []*plumbing.Reference, skipped []string, err error) {
	resolved, err := ar.ResolvedReferences()
	if err != nil {
		return nil, nil, fmt.Errorf("resolved references: %w", err)
	}
	out := resolved[:0]
	for _, ref := range resolved {
		if ref.Name().IsPeeled() {
			continue
		}

package syncer

import (
	"context"
	"slices"
	"testing"

	"entire.io/entire/git-sync/internal/gitproto"
	"github.com/go-git/go-billy/v6"
	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
)

// maximalFixture is a source whose branch master has two older branches
// behind it, already mirrored to a target. Every target tip but master's is
// an ancestor of master's.
type maximalFixture struct {
	source       *git.Repository
	sourceFS     billy.Filesystem
	target       *git.Repository
	targetServer *smartHTTPRepoServer
	sourceURL    string
	haves        *haveRecorder
	older        []plumbing.ReferenceName
	assume       bool
}

func newMaximalFixture(t *testing.T, advertise bool) *maximalFixture {
	t.Helper()
	sourceRepo, sourceFS := newSourceRepo(t)
	targetRepo, _ := newSourceRepo(t)
	makeCommits(t, sourceRepo, sourceFS, 3)
	f := &maximalFixture{source: sourceRepo, sourceFS: sourceFS, target: targetRepo, haves: &haveRecorder{}}

	commit, err := sourceRepo.CommitObject(f.tip(t, plumbing.NewBranchReferenceName(testBranch)))
	if err != nil {
		t.Fatalf("read master: %v", err)
	}
	for _, name := range []string{"older-a", "older-b"} {
		if commit, err = commit.Parent(0); err != nil {
			t.Fatalf("walk master: %v", err)
		}
		ref := plumbing.NewBranchReferenceName(name)
		if err := sourceRepo.Storer.SetReference(plumbing.NewHashReference(ref, commit.Hash)); err != nil {
			t.Fatalf("set %s: %v", ref, err)
		}
		f.older = append(f.older, ref)
	}

	sourceServer := newSmartHTTPRepoServerV2(t, sourceRepo)
	f.targetServer = newSmartHTTPRepoServerV2(t, targetRepo)
	f.targetServer.receivePackThinCap = true
	f.targetServer.lsRefsMaximal = advertise
	t.Cleanup(sourceServer.Close)
	t.Cleanup(f.targetServer.Close)
	f.haves.attach(sourceServer)
	f.sourceURL = sourceServer.RepoURL()

	if _, err := f.run(t, modeReplicate, ""); err != nil {
		t.Fatalf("seed replicate: %v", err)
	}
	assertSameRefs(t, sourceRepo, targetRepo)
	f.haves.take()
	return f
}

func (f *maximalFixture) run(t *testing.T, mode, protocol string) (Result, error) {
	t.Helper()
	return Run(context.Background(), Config{
		Source:       Endpoint{URL: f.sourceURL},
		Target:       Endpoint{URL: f.targetServer.RepoURL()},
		Mode:         mode,
		ProtocolMode: protocol,
		Branches:     []string{testBranch, "older-a", "older-b"},

		AssumeTargetMaximal: f.assume,
	})
}

func (f *maximalFixture) tip(t *testing.T, ref plumbing.ReferenceName) plumbing.Hash {
	t.Helper()
	r, err := f.source.Reference(ref, true)
	if err != nil {
		t.Fatalf("read %s: %v", ref, err)
	}
	return r.Hash()
}

// advance moves master on the source and returns its old tip.
func (f *maximalFixture) advance(t *testing.T) plumbing.Hash {
	t.Helper()
	before := f.tip(t, plumbing.NewBranchReferenceName(testBranch))
	makeCommits(t, f.source, f.sourceFS, 1)
	return before
}

func (f *maximalFixture) olderTips(t *testing.T) []plumbing.Hash {
	t.Helper()
	out := make([]plumbing.Hash, 0, len(f.older))
	for _, ref := range f.older {
		out = append(out, f.tip(t, ref))
	}
	return out
}

func assertEveryFetchHaves(t *testing.T, fetches [][]plumbing.Hash, want ...plumbing.Hash) {
	t.Helper()
	if len(fetches) == 0 {
		t.Fatal("no fetch reached the source")
	}
	for _, got := range fetches {
		assertFetchHaves(t, got, want...)
	}
}

// The case the feature exists for: the target marks only master, so the fetch
// offers master's old tip alone. The older branches are its ancestors.
func TestRun_IntegrationMaximalTipsShrinkHaves(t *testing.T) {
	for _, mode := range []string{modeSync, modeReplicate} {
		t.Run(mode, func(t *testing.T) {
			f := newMaximalFixture(t, true)
			before := f.advance(t)
			if _, err := f.run(t, mode, ""); err != nil {
				t.Fatalf("%s: %v", mode, err)
			}
			assertEveryFetchHaves(t, f.haves.take(), before)
			assertSameRefs(t, f.source, f.target)
			if args := f.targetServer.LastLSRefsArgs(); !slices.Contains(args, gitproto.MaximalFeature) {
				t.Errorf("target ls-refs args = %v, want %s", args, gitproto.MaximalFeature)
			}
		})
	}
}

// A target that does not advertise the feature never sees the argument, and
// every target tip stays a have.
func TestRun_IntegrationMaximalTipsUnadvertisedKeepsEveryTip(t *testing.T) {
	f := newMaximalFixture(t, false)
	before := f.advance(t)
	if _, err := f.run(t, modeReplicate, ""); err != nil {
		t.Fatalf("replicate: %v", err)
	}
	assertEveryFetchHaves(t, f.haves.take(), append(f.olderTips(t), before)...)
	assertSameRefs(t, f.source, f.target)
	if args := f.targetServer.LastLSRefsArgs(); slices.Contains(args, gitproto.MaximalFeature) {
		t.Errorf("target ls-refs args = %v; sent an argument the target did not advertise", args)
	}
}

// Pinning protocol v1 keeps the target listing off v2 entirely.
func TestRun_IntegrationMaximalTipsSkippedUnderV1(t *testing.T) {
	f := newMaximalFixture(t, true)
	f.targetServer.mu.Lock()
	f.targetServer.lsRefsArgs = nil
	f.targetServer.mu.Unlock()
	f.advance(t)
	if _, err := f.run(t, modeReplicate, protocolModeV1); err != nil {
		t.Fatalf("replicate: %v", err)
	}
	assertSameRefs(t, f.source, f.target)
	if args := f.targetServer.LastLSRefsArgs(); args != nil {
		t.Errorf("target ls-refs args = %v, want no ls-refs under protocol v1", args)
	}
}

// mirror-pipeline's case: entiredb accepts the argument before it advertises
// it, so the caller opts in and the haves shrink anyway.
func TestRun_IntegrationMaximalTipsAssumedWithoutAdvertisement(t *testing.T) {
	f := newMaximalFixture(t, false)
	f.assume = true
	before := f.advance(t)
	if _, err := f.run(t, modeReplicate, ""); err != nil {
		t.Fatalf("replicate: %v", err)
	}
	assertEveryFetchHaves(t, f.haves.take(), before)
	assertSameRefs(t, f.source, f.target)
	if args := f.targetServer.LastLSRefsArgs(); !slices.Contains(args, gitproto.MaximalFeature) {
		t.Errorf("target ls-refs args = %v, want %s", args, gitproto.MaximalFeature)
	}
}

// A target that rejects the assumed argument fails only the listing: the run
// offers every tip and completes.
func TestRun_IntegrationMaximalTipsAssumedButRejected(t *testing.T) {
	f := newMaximalFixture(t, false)
	f.assume = true
	f.targetServer.lsRefsRejectMaximal = true
	before := f.advance(t)
	if _, err := f.run(t, modeReplicate, ""); err != nil {
		t.Fatalf("replicate: %v", err)
	}
	assertEveryFetchHaves(t, f.haves.take(), append(f.olderTips(t), before)...)
	assertSameRefs(t, f.source, f.target)
}
package gitproto

import (
	"context"
	"io"
	"net/url"
)

// Conn represents a connection to a Git remote transport such as Smart HTTP
// or SSH.
type Conn interface {
	RequestInfoRefs(ctx context.Context, service string, gitProtocol string) ([]byte, error)
	PostRPCStreamBody(ctx context.Context, service string, body io.Reader, v2 bool, phase string) (io.ReadCloser, error)
	Endpoint() *url.URL
	ProgressWriter() io.Writer
	SetProgressWriter(w io.Writer)
	Close() error
}

package gitproto

import (
	"bufio"
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"net/url"
	"os"
	"os/exec"
	"slices"
	"strings"
	"sync"
)

// RemoteHelperLookPath resolves the git remote-helper binary for a URL scheme,
// following git's `git-remote-<scheme>` naming convention. Replaceable in
// tests; production wiring just calls exec.LookPath.
var RemoteHelperLookPath = func(scheme string) (string, bool) {
	path, err := exec.LookPath("git-remote-" + scheme)
	if err != nil {
		return "", false
	}
	return path, true
}

// LookupRemoteHelper reports whether a git remote helper is installed for the
// given URL scheme (e.g. "entire" → git-remote-entire). Schemes git-sync
// speaks natively (http/https/ssh) should never be routed here — git ships
// git-remote-http(s), and diverting to it would bypass the optimized native
// transport.
func LookupRemoteHelper(scheme string) (string, bool) {
	if scheme == "" {
		return "", false
	}
	return RemoteHelperLookPath(scheme)
}

// HelperConn speaks the git remote-helper protocol (gitremote-helpers(7)) to a
// git-remote-<scheme> binary, bridging git-sync's smart-transport Conn onto the
// helper's stateless-connect capability. It lets git-sync drive schemes it has
// no native transport for (e.g. entire://) by delegating auth and the actual
// network I/O to the helper, while still running the wire protocol itself.
//
// It requires the helper to support stateless-connect (the modern v2 bridge)
// for both upload-pack and receive-pack. It probes the helper's advertised
// capabilities first and fails with a clear error if stateless-connect is
// absent; it does not fall back to the legacy `connect` capability. A
// per-service "fallback" reply is also treated as an error. git-remote-entire
// satisfies this.
//
// Each Conn operation spawns its own helper process and tears it down when the
// operation completes. This is deliberate, not lazy: the helper services
// exactly one stateless-connect session per process (its protocol loop returns
// once the session ends), and its receive-pack path reads the pushed pack until
// stdin EOF — both of which make "fresh process per RPC" the simplest correct
// model, and it naturally supports git-sync's batched (multi-request) pushes.
// The cost is one extra info/refs request per RPC, negligible beside pack
// transfer.
//
// Like the SSH transport, the helper bridge has no per-request byte accounting,
// so --stats omits helper-side throughput.
type HelperConn struct {
	HelperPath  string
	EndpointURL *url.URL
	// RawURL is the user-typed URL (e.g. entire://host/path), passed to the
	// helper verbatim — the helper, not git-sync, owns scheme interpretation.
	RawURL      string
	Label       string
	progressOut io.Writer
}

// NewHelperConn builds a remote-helper-backed connection. helperPath is the
// resolved git-remote-<scheme> binary; rawURL is the URL as the user typed it.
func NewHelperConn(helperPath string, ep *url.URL, rawURL, label string) *HelperConn {
	return &HelperConn{HelperPath: helperPath, EndpointURL: ep, RawURL: rawURL, Label: label}
}

func (c *HelperConn) Endpoint() *url.URL { return c.EndpointURL }

func (c *HelperConn) ProgressWriter() io.Writer { return c.progressOut }

func (c *HelperConn) SetProgressWriter(w io.Writer) { c.progressOut = w }

// Close is a no-op: HelperConn owns no long-lived process. Each RPC manages its
// own helper process lifetime.
func (c *HelperConn) Close() error { return nil }

// RequestInfoRefs spawns the helper, opens a stateless-connect session for the
// service, and returns the advertisement the helper emits (the v2 capability
// advertisement for upload-pack, or the v0 ref advertisement for receive-pack).
// The helper strips the smart-HTTP "# service=" banner itself, so the bytes
// returned match what the SSH transport produces — bannerless and terminated by
// a flush, which both DecodeV2Capabilities and decodeV1AdvRefs already accept.
func (c *HelperConn) RequestInfoRefs(ctx context.Context, service string, gitProtocol string) ([]byte, error) {
	_ = gitProtocol // the helper negotiates v2 with the remote itself
	proc, err := c.dial(ctx, service)
	if err != nil {
		return nil, err
	}
	adv, readErr := readAdvertisement(proc.out)
	if readErr != nil {
		// cleanup, not finish: cleanup closes stdout, which makes a helper that
		// is still writing fail and exit. finish would try to drain first, and
		// against an endless stream that turns readAdvertisement's limit into a
		// hang rather than the error we want to report.
		return nil, fmt.Errorf("%s advertisement: %w", service, errors.Join(readErr, proc.cleanup()))
	}
	if err := proc.finish(); err != nil {
		return nil, fmt.Errorf("%s advertisement: %w", service, err)
	}
	return adv, nil
}

// PostRPCStreamBody spawns the helper, opens a stateless-connect session, sends
// the request body, and returns the response stream. The helper always emits
// ack + advertisement before reading the request, so the advertisement is
// consumed and discarded first. For v2 the helper frames each response with a
// trailing response-end (0002) packet, which is stripped so the consumer sees
// exactly the byte stream it would over HTTP; for v0 (receive-pack) the response
// runs to EOF.
func (c *HelperConn) PostRPCStreamBody(ctx context.Context, service string, body io.Reader, v2 bool, phase string) (io.ReadCloser, error) {
	_ = phase // helper transport has no per-RPC byte-stats tagging (like SSH)
	proc, err := c.dial(ctx, service)
	if err != nil {
		return nil, err
	}
	if _, err := readAdvertisement(proc.out); err != nil {
		return nil, fmt.Errorf("%s advertisement: %w", service, errors.Join(err, proc.cleanup()))
	}

	copyErr := make(chan error, 1)
	go func() {
		_, err := io.Copy(proc.stdin, body)
		// Closing stdin terminates the request: it bounds the v2
		// flush-terminated read and, crucially, signals end-of-pack to the
		// receive-pack handler, which copies the pack until EOF.
		closeErr := proc.stdin.Close()
		if err != nil {
			copyErr <- err
			return
		}
		copyErr <- closeErr
	}()

	var resp io.Reader = proc.out
	if v2 {
		resp = newResponseEndReader(proc.out)
	}
	return &helperRPCStream{ctx: ctx, resp: resp, proc: proc, copyErr: copyErr}, nil
}

// dial starts the helper process and opens a stateless-connect session for the
// service, consuming the helper's single-line acknowledgement. On success the
// helper is positioned to emit its advertisement.
func (c *HelperConn) dial(ctx context.Context, service string) (*helperProcess, error) {
	// git invokes a remote helper as `git-remote-<scheme> <remote> <url>`.
	// Passing the user-typed URL for both arguments matches git's handling of
	// an anonymous (URL-only) remote, which is what git-sync always has.
	cmd := exec.CommandContext(ctx, c.HelperPath, c.RawURL, c.RawURL)
	// GIT_PROTOCOL=version=2 makes the helper advertise stateless-connect; we
	// drive stateless-connect directly regardless, but this keeps the helper's
	// own negotiation aligned with how we use it.
	cmd.Env = append(os.Environ(), "GIT_PROTOCOL="+GitProtocolV2)
	stderr := &sshCommandError{}
	cmd.Stderr = stderr
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return nil, fmt.Errorf("open helper stdout: %w", err)
	}
	stdin, err := cmd.StdinPipe()
	if err != nil {
		return nil, fmt.Errorf("open helper stdin: %w", err)
	}
	if err := cmd.Start(); err != nil {
		return nil, fmt.Errorf("start remote helper %s: %w", c.HelperPath, stderr.wrap(err))
	}
	proc := &helperProcess{
		cmd:    cmd,
		stdin:  stdin,
		stdout: stdout,
		out:    bufio.NewReaderSize(stdout, 65536),
		stderr: stderr,
	}
	// Probe capabilities first so an incompatible helper produces a clear error
	// instead of a cryptic mid-protocol failure. This is a local exchange — no
	// network round trip happens until stateless-connect below.
	caps, err := proc.readCapabilities()
	if err != nil {
		return nil, fmt.Errorf("probe remote helper %s: %w", c.HelperPath, errors.Join(err, proc.cleanup()))
	}
	if !slices.Contains(caps, "stateless-connect") {
		unsupported := fmt.Errorf("remote helper %s does not support stateless-connect (advertises: %s); git-sync needs a stateless-connect-capable helper such as git-remote-entire",
			c.HelperPath, strings.Join(caps, " "))
		return nil, errors.Join(unsupported, proc.cleanup())
	}
	if _, err := io.WriteString(stdin, "stateless-connect "+service+"\n"); err != nil {
		return nil, fmt.Errorf("request stateless-connect %s: %w", service, errors.Join(err, proc.cleanup()))
	}
	if err := proc.readAck(); err != nil {
		return nil, fmt.Errorf("stateless-connect %s: %w", service, errors.Join(err, proc.cleanup()))
	}
	return proc, nil
}

// helperProcess wraps a single helper invocation and its pipes.
type helperProcess struct {
	cmd    *exec.Cmd
	stdin  io.WriteCloser
	stdout io.ReadCloser
	out    *bufio.Reader
	stderr *sshCommandError

	stdinOnce sync.Once
}

// readCapabilities issues the helper's `capabilities` command and returns the
// advertised capability names (the token before any argument on each line),
// reading until the blank terminator line.
func (p *helperProcess) readCapabilities() ([]string, error) {
	if _, err := io.WriteString(p.stdin, "capabilities\n"); err != nil {
		return nil, fmt.Errorf("request capabilities: %w", err)
	}
	var caps []string
	for {
		line, err := p.out.ReadString('\n')
		if err != nil {
			return nil, fmt.Errorf("read capabilities: %w", p.stderr.wrap(err))
		}
		if line = strings.TrimRight(line, "\r\n"); line == "" {
			return caps, nil
		}
		name, _, _ := strings.Cut(line, " ")
		caps = append(caps, name)
	}
}

// readAck consumes the helper's stateless-connect response line: an empty line
// means the connection is established, "fallback" means it can't proxy this
// service, and anything else is an error (with captured stderr).
func (p *helperProcess) readAck() error {
	line, err := p.out.ReadString('\n')
	if err != nil {
		return fmt.Errorf("read helper response: %w", p.stderr.wrap(err))
	}
	switch strings.TrimRight(line, "\r\n") {
	case "":
		return nil
	case "fallback":
		return errors.New("remote helper cannot proxy this service (fallback)")
	default:
		return fmt.Errorf("unexpected helper response %q: %s", strings.TrimRight(line, "\r\n"), p.stderr.String())
	}
}

func (p *helperProcess) closeStdin() error {
	var err error
	p.stdinOnce.Do(func() { err = p.stdin.Close() })
	if err != nil {
		return fmt.Errorf("close helper stdin: %w", err)
	}
	return nil
}

func (p *helperProcess) wait() error {
	if err := p.cmd.Wait(); err != nil {
		return p.stderr.wrap(fmt.Errorf("remote helper: %w", err))
	}
	return nil
}

// maxDrainBytes bounds finish's trailing-output drain. A compliant helper
// writes nothing of consequence after the advertisement, so this only ever
// absorbs a small tail. The bound matters because an unbounded drain against a
// helper that keeps writing never returns — which would defeat
// readAdvertisement's own limit by hanging here instead of reporting it.
const maxDrainBytes = 1 << 20

// finish closes the request side and waits for the helper to exit cleanly,
// draining any trailing output so cmd.Wait doesn't race the stdout pipe. Used
// by RequestInfoRefs, which needs only the advertisement.
func (p *helperProcess) finish() error {
	closeErr := p.closeStdin()
	//nolint:errcheck // best-effort drain before Wait; exit status is authoritative
	drained, _ := io.Copy(io.Discard, io.LimitReader(p.out, maxDrainBytes+1))
	if drained > maxDrainBytes {
		// Still producing well past any legitimate tail. Close the pipe so the
		// write side fails and the process can exit, instead of blocking
		// forever on a full pipe and taking p.wait() with it.
		_ = p.stdout.Close()
	}
	return errors.Join(closeErr, p.wait())
}

// cleanup force-tears-down the process on an error path.
func (p *helperProcess) cleanup() error {
	_ = p.closeStdin() //nolint:errcheck // force-teardown path; wait status is the reported error
	_ = p.stdout.Close()
	return p.wait()
}

// readAdvertisement reads raw pkt-lines up to and including the first flush
// (0000) and returns them verbatim. This is the helper's service advertisement;
// the trailing flush is preserved because both advertisement decoders consume
// it as the section terminator.
//
// Accumulation is bounded by MaxAdvertisementBytes, the same ceiling the HTTP
// and SSH transports use: a helper that streams pkt-lines and never sends the
// flush would otherwise grow this buffer until the process died.
func readAdvertisement(br *bufio.Reader) ([]byte, error) {
	var buf bytes.Buffer
	var scratch []byte
	for {
		kind, frame, err := readRawPktLine(br, scratch)
		if err != nil {
			return nil, fmt.Errorf("read advertisement pkt-line: %w", err)
		}
		buf.Write(frame)
		if buf.Len() > MaxAdvertisementBytes {
			return nil, fmt.Errorf("helper advertisement exceeds %d byte limit", MaxAdvertisementBytes)
		}
		scratch = frame // reuse the (possibly grown) backing buffer next iteration
		if kind == PacketFlush {
			return buf.Bytes(), nil
		}
	}
}

// responseEndReader re-emits a helper's framed v2 response verbatim, returning
// io.EOF when it reaches the stateless-connect response-end (0002) packet. The
// 0002 is consumed but never forwarded, so the downstream protocol parser sees
// exactly the same bytes it would from an HTTP response body (which ends at the
// connection's EOF instead). The frame buffer is reused across packets, so
// relaying a multi-GB pack costs no per-packet allocation.
type responseEndReader struct {
	src     *bufio.Reader
	buf     []byte // reused backing for the current frame
	pending []byte // unread bytes of the current frame (sub-slice of buf)
	done    bool
}

func newResponseEndReader(src *bufio.Reader) *responseEndReader {
	return &responseEndReader{src: src}
}

func (r *responseEndReader) Read(p []byte) (int, error) {
	for len(r.pending) == 0 {
		if r.done {
			return 0, io.EOF
		}
		if err := r.fill(); err != nil {
			return 0, err
		}
	}
	n := copy(p, r.pending)
	r.pending = r.pending[n:]
	return n, nil
}

func (r *responseEndReader) fill() error {
	kind, frame, err := readRawPktLine(r.src, r.buf)
	if err != nil {
		return fmt.Errorf("read response pkt-line: %w", err)
	}
	if kind == PacketResponseEnd {
		r.done = true
		return io.EOF
	}
	r.buf = frame // retain the grown backing for the next fill
	r.pending = frame
	return nil
}

// helperRPCStream is the io.ReadCloser returned for a helper RPC response. It
// forwards reads from the (optionally response-end-bounded) helper stdout and,
// on Close, tears the process down: closing both pipes (which unblocks the body
// writer if the consumer bailed mid-stream), then joining the body-copy error,
// the process exit status, and any captured stderr.
type helperRPCStream struct {
	ctx     context.Context
	resp    io.Reader
	proc    *helperProcess
	copyErr <-chan error

	closeOnce sync.Once
	closeErr  error
}

func (s *helperRPCStream) Read(p []byte) (int, error) {
	n, err := s.resp.Read(p)
	return n, err //nolint:wrapcheck // io.Reader contract requires forwarding EOF and stream errors as-is
}

func (s *helperRPCStream) Close() error {
	s.closeOnce.Do(func() {
		_ = s.proc.closeStdin() //nolint:errcheck // unblocks the body writer; copy/wait errors below are authoritative
		closeOut := s.proc.stdout.Close()
		copyErr := <-s.copyErr
		waitErr := s.proc.wait()

		s.closeErr = errors.Join(copyErr, waitErr)
		if s.closeErr == nil && closeOut != nil && !errors.Is(closeOut, os.ErrClosed) {
			s.closeErr = closeOut
		}
		if s.ctx != nil && s.ctx.Err() != nil {
			s.closeErr = errors.Join(s.ctx.Err(), s.closeErr)
		}
	})
	return s.closeErr
}
package gitproto

import (
	"github.com/go-git/go-git/v6/plumbing/protocol/capability"
	"github.com/go-git/go-git/v6/plumbing/protocol/packp"
)

// TargetFeatures summarizes the receive-pack capabilities relevant to strategy
// selection and push behavior.
type TargetFeatures struct {
	Known        bool `json:"known"`
	DeleteRefs   bool `json:"deleteRefs"`
	NoThin       bool `json:"noThin"`
	OFSDelta     bool `json:"ofsDelta"`
	ReportStatus bool `json:"reportStatus"`
	Sideband     bool `json:"sideband"`
	Sideband64k  bool `json:"sideband64k"`
}

// TargetFeaturesFromAdvRefs derives the target-side feature summary from a
// receive-pack advertisement.
func TargetFeaturesFromAdvRefs(adv *packp.AdvRefs) TargetFeatures {
	if adv == nil || adv.Capabilities.IsEmpty() {
		return TargetFeatures{}
	}
	return TargetFeatures{
		Known:        true,
		DeleteRefs:   adv.Capabilities.Supports(capability.DeleteRefs),
		NoThin:       adv.Capabilities.Supports(capability.Capability("no-thin")),
		OFSDelta:     adv.Capabilities.Supports(capability.OFSDelta),
		ReportStatus: adv.Capabilities.Supports(capability.ReportStatus),
		Sideband:     adv.Capabilities.Supports(capability.Sideband),
		Sideband64k:  adv.Capabilities.Supports(capability.Sideband64k),
	}
}
