func TestReviewFreshMaximalProbeRedirectCredentialScope(t *testing.T) {
 var readerAuth string
 rt := roundTripperFunc(func(req *http.Request) (*http.Response,error) {
  res := &http.Response{StatusCode:200, Request:req, Header:make(http.Header), Body:io.NopCloser(strings.NewReader("0000"))}
  if req.URL.Host=="writer.example" {
   if req.Header.Get("Authorization")=="" { return newUnauthorizedResponse(req),nil }
   res.StatusCode=307
   res.Header.Set("Location","https://reader.other/repo.git/info/refs?service=git-upload-pack")
  } else if req.Method==http.MethodGet {
   res.Header.Set("Content-Type","application/x-git-upload-pack-advertisement")
   res.Body=io.NopCloser(bytes.NewReader(pktBody(t,"version 2","ls-refs="+MaximalFeature,"fetch")))
  } else {
   readerAuth=req.Header.Get("Authorization")
   res.Body=io.NopCloser(bytes.NewReader(pktBody(t,maxA.String()+" refs/heads/main "+MaximalFeature)))
  }
  return res,nil
 })
 ep,_:=url.Parse("https://writer.example/repo.git")
 conn:=NewHTTPConn(ep,"review",nil,rt)
 conn.FollowInfoRefsRedirect=true
 conn.CredentialHelper=&fakeCredentialHelper{user:"review",pass:"dummy-secret",ok:true}
 if _,err:=ListMaximalTips(t.Context(),conn,nil,false);err!=nil {t.Fatal(err)}
 t.Logf("ls-refs POST to reader.other carries writer helper credential=%t",readerAuth!="")
 if readerAuth!="" {t.Error("fresh maximal probe leaks writer helper credential to unrelated reader")}
}
